#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
const int INF = 0x3f3f3f3f;
const ll MOD = 1000000007LL;
const int Z = 100;
const int MAX_NODES = Z * Z;
const int MAX_EDGES = Z * Z * Z * 3;

int n, m, k, c_val, d_val;
int source, sink;
vector<vector<int>> adj(MAX_NODES);
vector<int> capacity(MAX_EDGES), cost(MAX_EDGES);
vector<int> next_edge(MAX_EDGES);
vector<int> to_node(MAX_EDGES);
int dist[MAX_NODES], visited[MAX_NODES], parent[MAX_NODES], edge_id[MAX_NODES];

void add_edge(int u, int v, int cap, int c) {
    int idx1 = adj[u].size();
    int idx2 = adj[v].size();

    adj[u].push_back((int)adj[v].size());
    adj[v].push_back((int)adj[u].size() - 1);

    capacity[idx1 * 2] = cap;
    cost[idx1 * 2] = c;
    to_node[idx1 * 2] = v;

    capacity[idx1 * 2 + 1] = 0;
    cost[idx1 * 2 + 1] = -c;
    to_node[idx1 * 2 + 1] = u;
}

bool spfa(int s, int t) {
    fill(dist, dist + MAX_NODES, INF);
    fill(visited, visited + MAX_NODES, 0);
    fill(parent, parent + MAX_NODES, -1);

    queue<int> q;
    dist[s] = 0;
    q.push(s);
    visited[s] = 1;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = 0;

        for (int idx : adj[u]) {
            if (capacity[idx] > 0 && dist[to_node[idx]] > dist[u] + cost[idx]) {
                dist[to_node[idx]] = dist[u] + cost[idx];
                parent[to_node[idx]] = u;
                edge_id[to_node[idx]] = idx;
                if (!visited[to_node[idx]]) {
                    visited[to_node[idx]] = 1;
                    q.push(to_node[idx]);
                }
            }
        }
    }

    return dist[t] < INF;
}

int min_cost_max_flow(int s, int t) {
    int total_flow = 0;
    int total_cost = 0;

    while (spfa(s, t)) {
        int flow = INF;
        for (int v = t; v != s; v = parent[v]) {
            flow = min(flow, capacity[edge_id[v]]);
        }

        for (int v = t; v != s; v = parent[v]) {
            capacity[edge_id[v]] -= flow;
            capacity[edge_id[v] ^ 1] += flow;
        }

        total_flow += flow;
        total_cost += dist[t] * flow;
    }

    return total_cost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m >> k >> c_val >> d_val;

    source = 0;
    sink = n * 100 + 1;

    // Connect each node at level 100 to sink with capacity 100 and cost 0
    for (int i = 1; i <= 100; ++i) {
        int node = i;
        int to_sink = sink;
        add_edge(node, to_sink, 100, 0);
    }

    // Add edges from source to starting nodes
    for (int i = 0; i < k; ++i) {
        int v;
        cin >> v;
        add_edge(source, (v - 1) * 100 + 1, 1, 0);
    }

    // Add internal edges within each node: level j to j+1
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            int from = (i - 1) * 100 + j;
            int to = (i - 1) * 100 + j + 1;
            add_edge(from, to, 100, c_val);
        }
    }

    // Add bidirectional edges between connected nodes
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;

        for (int j = 1; j < 100; ++j) {
            int idx1 = (u - 1) * 100 + j;
            int idx2 = (v - 1) * 100 + j + 1;

            for (int step = 1; step <= 50; ++step) {
                int edge_cost = c_val + (step * step - (step - 1) * (step - 1)) * d_val;
                add_edge(idx1, idx2, 1, edge_cost);
            }
        }

        for (int j = 1; j < 100; ++j) {
            int idx1 = (v - 1) * 100 + j;
            int idx2 = (u - 1) * 100 + j + 1;

            for (int step = 1; step <= 50; ++step) {
                int edge_cost = c_val + (step * step - (step - 1) * (step - 1)) * d_val;
                add_edge(idx1, idx2, 1, edge_cost);
            }
        }
    }

    cout << min_cost_max_flow(source, sink) << '\n';

    return 0;
}
